    bank_records: list[dict[str, Any]],
    internal_orders: list[dict[str, Any]],
) -> dict[str, list[dict[str, Any]]]:
    """Concilia extractos bancarios PSE con órdenes internas en O(N + M).
    Maneja duplicados de webhook e identifica discrepancias de monto."""

for b in bank_records:
